export function normalizeRepoReference(repo: string): string {
  if (!repo) return '';

  // Remove trailing .git if present
  let normalized = repo.replace(/\.git$/, '');

  // Handle full GitHub URLs
  if (normalized.startsWith('https://github.com/')) {
    normalized = normalized.replace('https://github.com/', '');
  } else if (normalized.startsWith('http://github.com/')) {
    normalized = normalized.replace('http://github.com/', '');
  } else if (normalized.startsWith('git@github.com:')) {
    normalized = normalized.replace('git@github.com:', '');
  }

  // Trim and remove trailing slashes
  normalized = normalized.trim().replace(/\/+$/, '');

  // Extract just owner/repo (ignore extra path segments like /tree/main)
  const parts = normalized.split('/');
  if (parts.length >= 2) {
    normalized = `${parts[0]}/${parts[1]}`;
  }

  // Validate format: should be exactly "owner/repo"
  if (!/^[^\/]+\/[^\/]+$/.test(normalized)) {
    return '';
  }

  return normalized;
}
```

</details>

<!-- suggestion_end -->

