    const profile: APIProfile = {
      id: generateProfileId(),
      name: input.name.trim(),
      baseUrl: input.baseUrl.trim(),
      apiKey: input.apiKey.trim(),
      models: input.models,
      createdAt: now,
      updatedAt: now
    };

    createdProfileId = profile.id;

    // Add to profiles list
