 */
async function executePythonScript<T>(
    pythonCode: string,
    stdinData?: Record<string, unknown>
): Promise<IPCResult<T>> {
    return new Promise((resolve) => {
        try {
            const backendPath = getBackendPathForIntegrations();
            const pythonPath = getPythonPathForIntegrations();

            const python = spawn(pythonPath, ['-c', pythonCode], {
                cwd: backendPath,
                env: { ...process.env, PYTHONPATH: backendPath }
            });

            if (stdinData) {
                python.stdin.write(JSON.stringify(stdinData));
                python.stdin.end();
            }

            let output = '';
            let errorOutput = '';

            python.stdout.on('data', (data) => {
                output += data.toString();
            });

            python.stderr.on('data', (data) => {
                errorOutput += data.toString();
            });

            python.on('close', (code) => {
                if (code !== 0) {
                    resolve({
                        success: false,
                        error: `Python script failed: ${errorOutput}`
                    });
                    return;
                }

                try {
                    const result = JSON.parse(output.trim());
                    resolve({ success: true, data: result });
                } catch (e) {
                    resolve({
                        success: false,
                        error: `Failed to parse Python output: ${e}`
                    });
                }
            });

            python.on('error', (error) => {
                resolve({
                    success: false,
                    error: `Failed to spawn Python: ${error.message}`
                });
            });
        } catch (error) {
            resolve({
                success: false,
                error: error instanceof Error ? error.message : 'Unknown error'
            });
        }
    });
}

