  require('child_process').execSync('some-command-that-fails')
} catch (err) {
  console.log('exit code:', err.status)   // exit code (number or null)
  console.log('signal:', err.signal)      // signal that killed it (if any)
  console.log('stdout:', err.stdout)      // Buffer|string
  console.log('stderr:', err.stderr)      // Buffer|string
}

Sources: Node.js child_process docs (execSync / spawnSync result fields). [1][2]

